gsap.registerPlugin(ScrollTrigger);

/* =========================
   HELPER
========================= */
const get = (el, key, def) => {
  const val = el.dataset[key];
  if (val === undefined) return def;
  if (val === "true") return true;
  if (val === "false") return false;
  if (!isNaN(val)) return parseFloat(val);
  return val;
};

/* =========================
   TARGET RESOLVER
========================= */
const resolveTarget = (el) => {
  const t = el.dataset.target;

  if (!t) return el.querySelector("img") || el;
  if (t === "self") return el;
  if (t === "parent") return el.parentElement;

  return el.querySelector(t) || el;
};

/* =========================
   TRIGGER RESOLVER
========================= */
const resolveTrigger = (el) => {
  const t = el.dataset.trigger;

  if (!t || t === "false") return el;
  if (t === "parent") return el.parentElement;

  return document.querySelector(t) || el;
};

/* =========================
   SCROLLTRIGGER CONFIG
========================= */
const commonST = (el) => {
  const scrub = get(el, "scrub", false);
  const reverse = get(el, "reverse", false);
  const triggerEl = resolveTrigger(el);

  if (scrub) {
    return {
      trigger: triggerEl,
      start: get(el, "start", "top 85%"),
      end: get(el, "end", "bottom top"),
      scrub: scrub
    };
  }

  return {
    trigger: triggerEl,
    start: get(el, "start", "top 85%"),
    end: get(el, "end", "bottom top"),

    onEnter: (self) => self.animation.play(),
    onEnterBack: (self) => self.animation.play(),

    onLeave: (self) => reverse && self.animation.reverse(),
    onLeaveBack: (self) => reverse && self.animation.reverse()
  };
};

/* =========================
   APPLY
========================= */
const apply = (el, from, to) => {
  const target = resolveTarget(el);
  const scrub = get(el, "scrub", false);

  if (scrub) {
    return gsap.fromTo(target, from, {
      ...to,
      ease: "none",
      immediateRender: false,
      scrollTrigger: commonST(el),
      onStart: () => {
        target.style.visibility = "visible";
        target.style.opacity = "1";
      }
    });
  }

  gsap.set(target, {
    ...from,
    opacity: 1,
    visibility: "visible"
  });

  const tween = gsap.to(target, {
    ...to,
    opacity: 1,
    ease: to.ease || "power2.inOut",
    duration: to.duration || get(el, "duration", 1.2),
    delay: to.delay || get(el, "delay", 0),
    paused: true
  });

  ScrollTrigger.create({
    ...commonST(el),
    animation: tween
  });

  return tween;
};

/* =========================
   PRESETS
========================= */
const presets = {

  /* ========= MASK BASIC ========= */
  "mask-right": (el) => apply(el,
    { clipPath: "inset(0% 100% 0% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-left": (el) => apply(el,
    { clipPath: "inset(0% 0% 0% 100%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-top": (el) => apply(el,
    { clipPath: "inset(100% 0% 0% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-bottom": (el) => apply(el,
    { clipPath: "inset(0% 0% 100% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  /* ========= MASK CENTER ========= */
  "mask-center": (el) => apply(el,
    { clipPath: "inset(50% 50% 50% 50%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-center-horizontal": (el) => apply(el,
    { clipPath: "inset(0% 50% 0% 50%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-center-vertical": (el) => apply(el,
    { clipPath: "inset(50% 0% 50% 0%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-cross": (el) => apply(el,
    { clipPath: "inset(50% 50% 50% 50%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  "mask-frame": (el) => apply(el,
    { clipPath: "inset(20% 20% 20% 20%)" },
    { clipPath: "inset(0% 0% 0% 0%)" }
  ),

  /* ========= SHAPES ========= */
  "mask-diamond": (el) => apply(el,
    { clipPath: "polygon(50% 50%, 50% 50%, 50% 50%, 50% 50%)" },
    { clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)" }
  ),

  "mask-triangle-top": (el) => apply(el,
    { clipPath: "polygon(50% 0%, 50% 0%, 50% 0%)" },
    { clipPath: "polygon(50% 0%, 100% 100%, 0% 100%)" }
  ),

  "mask-triangle-bottom": (el) => apply(el,
    { clipPath: "polygon(50% 100%, 50% 100%, 50% 100%)" },
    { clipPath: "polygon(0% 0%, 100% 0%, 50% 100%)" }
  ),

  /* ========= DIAGONAL ========= */
  "mask-diagonal-1": (el) => apply(el,
    { clipPath: "polygon(0 0, 0 0, 0 100%, 0 100%)" },
    { clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }
  ),

  "mask-diagonal-2": (el) => apply(el,
    { clipPath: "polygon(100% 0, 100% 0, 100% 100%, 100% 100%)" },
    { clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }
  ),

  "mask-diagonal-wipe": (el) => apply(el,
    { clipPath: "polygon(0 0, 100% 0, 0 0, 0 100%)" },
    { clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }
  ),

  /* ========= CIRCLE ========= */
  "circle-center": (el) => apply(el,
    { clipPath: "circle(0% at 50% 50%)" },
    { clipPath: "circle(100% at 50% 50%)" }
  ),

  "circle-left": (el) => apply(el,
    { clipPath: "circle(0% at 0% 50%)" },
    { clipPath: "circle(150% at 0% 50%)" }
  ),

  "circle-right": (el) => apply(el,
    { clipPath: "circle(0% at 100% 50%)" },
    { clipPath: "circle(150% at 100% 50%)" }
  ),

  /* ========= TRANSFORM ========= */
  "zoom-in": (el) => apply(el,
    { scale: 1.5, opacity: 0 },
    { scale: 1, opacity: 1 }
  ),

  "zoom-out": (el) => apply(el,
    { scale: 0.5, opacity: 0 },
    { scale: 1, opacity: 1 }
  ),

  "slide-up": (el) => apply(el,
    { y: 80, opacity: 0 },
    { y: 0, opacity: 1 }
  ),

  "slide-down": (el) => apply(el,
    { y: -80, opacity: 0 },
    { y: 0, opacity: 1 }
  ),

  "slide-left": (el) => apply(el,
    { x: 80, opacity: 0 },
    { x: 0, opacity: 1 }
  ),

  "slide-right": (el) => apply(el,
    { x: -80, opacity: 0 },
    { x: 0, opacity: 1 }
  ),

  /* ========= EFFECTS ========= */
  "rotate-in": (el) => apply(el,
    { rotate: -180, opacity: 0 },
    { rotate: 0, opacity: 1 }
  ),

  "rotate-scale": (el) => apply(el,
    { rotate: 45, scale: 0.5, opacity: 0 },
    { rotate: 0, scale: 1, opacity: 1 }
  ),

  "flip-x": (el) => apply(el,
    { rotateX: 90, opacity: 0 },
    { rotateX: 0, opacity: 1 }
  ),

  "flip-y": (el) => apply(el,
    { rotateY: 90, opacity: 0 },
    { rotateY: 0, opacity: 1 }
  ),

  "blur-in": (el) => apply(el,
    { filter: "blur(20px)", opacity: 0 },
    { filter: "blur(0px)", opacity: 1 }
  ),

  "skew-in": (el) => apply(el,
    { skewX: 20, opacity: 0 },
    { skewX: 0, opacity: 1 }
  ),

  "bounce-in": (el) => apply(el,
    { scale: 0.3, opacity: 0 },
    { scale: 1, opacity: 1, ease: "back.out(1.7)" }
  ),

  "fade-in-fast": (el) => apply(el,
    { opacity: 0 },
    { opacity: 1, duration: 0.3 }
  ),

  "glitch-in": (el) => apply(el,
    { x: -10, opacity: 0 },
    { x: 0, opacity: 1, duration: 0.2, ease: "steps(2)" }
  ),

  "pop-in": (el) => apply(el,
    { scale: 0, opacity: 0 },
    { scale: 1, opacity: 1, ease: "back.out(2)" }
  ),

  "float-up": (el) => apply(el,
    { y: 40, opacity: 0 },
    { y: 0, opacity: 1, ease: "power2.out" }
  )

};

/* =========================
   INIT
========================= */
window.addEventListener("load", () => {
  document.querySelectorAll("[data-reveal]").forEach(el => {
    const type = el.dataset.reveal;
    if (presets[type]) presets[type](el);
  });
});